def _replay_balanced_design_execution_for_result_decision(
    *,
    repository: PostgresResearchOSRepository,
    root_dir: Path,
    control_plane_key: str,
) -> tuple[
    Mapping[str, Any],
    Mapping[str, Any],
    Mapping[str, Any],
    Mapping[str, Any],
    Mapping[str, Any],
]:
    _, execution, registrations = _load_single_completed_execution(
        repository=repository,
        root_dir=root_dir,
        control_plane_key=control_plane_key,
        task_key=PREDICTION_V2_BALANCED_DESIGN_FEASIBILITY_EXECUTION_TASK_KEY,
    )
    inventory = _load_registered_type(
        root_dir=root_dir,
        registrations=registrations,
        artifact_type="PredictionV2BalancedDesignOrbitInventoryArtifact",
    )
    result = _load_registered_type(
        root_dir=root_dir,
        registrations=registrations,
        artifact_type="PredictionV2BalancedDesignSearchResultArtifact",
    )
    completion = _load_registered_type(
        root_dir=root_dir,
        registrations=registrations,
        artifact_type="prediction_v2_balanced_design_feasibility_execution_completion",
    )
    execution_source = load_execution_source_contract(
        root_dir
        / PREDICTION_V2_BALANCED_DESIGN_FEASIBILITY_EXECUTION_SOURCE_CONTRACT_PATH
    )
    verify_execution_source_bytes(root_dir=root_dir, contract=execution_source)
    _, preregistration_execution, preregistration_registrations = (
        _load_single_completed_execution(
            repository=repository,
            root_dir=root_dir,
            control_plane_key=control_plane_key,
            task_key=(
                PREDICTION_V2_BALANCED_DESIGN_FEASIBILITY_PREREGISTRATION_TASK_KEY
            ),
        )
    )
    preregistration = _load_registered_type(
        root_dir=root_dir,
        registrations=preregistration_registrations,
        artifact_type="prediction_v2_balanced_design_feasibility_preregistration",
    )
    execution_handoff = _load_registered_type(
        root_dir=root_dir,
        registrations=preregistration_registrations,
        artifact_type="prediction_v2_balanced_design_feasibility_execution_handoff",
    )
    preregistration_completion = _load_registered_type(
        root_dir=root_dir,
        registrations=preregistration_registrations,
        artifact_type=(
            "prediction_v2_balanced_design_feasibility_preregistration_completion"
        ),
    )
    execution_replay = replay_balanced_design_execution(
        source_contract=execution_source,
        preregistration=preregistration,
        execution_handoff=execution_handoff,
        preregistration_completion=preregistration_completion,
        preregistration_mainline_execution=preregistration_execution,
        inventory_artifact=inventory,
        result_artifact=result,
        completion_artifact=completion,
        execution_id=str(execution["execution_id"]),
        checkpoint_path=(
            root_dir
            / "runtime/research-os/mainline/tasks"
            / PREDICTION_V2_BALANCED_DESIGN_FEASIBILITY_EXECUTION_TASK_KEY
            / str(execution["execution_id"])
            / "checkpoints/search.jsonl"
        ),
    )
    return execution, inventory, result, completion, execution_replay


